// Basis nur zum Auflösen relativer Pfade; .invalid ist reserviert (RFC 2606) und nie erreichbar.
const ZIEL_BASIS = "https://ziel.invalid";
// Unsicher: Steuerzeichen (C0/C1), Leerzeichen, Unicode-Leer-, Zero-Width- und Richtungszeichen, BOM, Backslash.
// Als Codepunkte geprüft, damit keine unsichtbaren Zeichen im Quelltext stehen.
function unsicheresZeichen(s) {
  for (const c of s) {
    const n = c.codePointAt(0);
    if (n <= 0x20 || (n >= 0x7f && n <= 0xa0) || n === 0x5c || n === 0x1680 || n === 0x3000 || n === 0xfeff) return true;
    if ((n >= 0x2000 && n <= 0x200f) || (n >= 0x2028 && n <= 0x202f) || (n >= 0x205f && n <= 0x206f)) return true;
  }
  return false;
}

/**
 * Nur interne Pfade als Ziel nach dem Login zulassen (kein Open Redirect).
 *
 * Browser entfernen beim URL-Parsen Tab/CR/LF und deuten "\" wie "/" (WHATWG URL Standard):
 * "/\t/evil.com" wird so zu "//evil.com" und damit zu https://evil.com. Deshalb werden Steuer-,
 * Leerzeichen und Backslashes komplett abgelehnt, und das Ergebnis wird zusätzlich aufgelöst
 * und muss auf derselben Herkunft bleiben. Zurück kommt der normalisierte Pfad
 * (z. B. "/x/../api/…" wird als "/api/…" erkannt und abgelehnt).
 * Test: node --test src/lib/plattform/sicheresZiel.test.mjs
 */
export function sicheresZiel(weiter, standard = "/portal") {
  const w = String(weiter || "");
  if (!w.startsWith("/") || w.startsWith("//") || unsicheresZeichen(w)) return standard;
  let u;
  try {
    u = new URL(w, ZIEL_BASIS);
  } catch {
    return standard;
  }
  if (u.origin !== ZIEL_BASIS) return standard;
  const pfad = `${u.pathname}${u.search}${u.hash}`;
  return /^\/api(\/|$)/i.test(u.pathname) ? standard : pfad;
}
// Tests der Open-Redirect-Prüfung:  node --test src/lib/plattform/sicheresZiel.test.mjs
// Abnahme Paket A: "/%09/evil.com" leitet nicht weiter.
import test from "node:test";
import assert from "node:assert/strict";
import { sicheresZiel } from "./client.js";

const BASIS = "https://www.oekoinvest.com/";
// Wohin würde ein Browser mit diesem Ziel tatsächlich gehen?
const herkunft = (ziel) => new URL(ziel, BASIS).origin;

test("/%09/evil.com (nach Dekodierung Tab) wird abgelehnt", () => {
  const weiter = new URLSearchParams("weiter=/%09/evil.com").get("weiter");
  assert.equal(weiter, "/\t/evil.com");
  assert.equal(sicheresZiel(weiter, "/portal"), "/portal");
});

test("bekannte Umgehungen landen nie auf fremder Herkunft", () => {
  const angriffe = [
    "//evil.com", "/\\evil.com", "/\\/evil.com", "\\\\evil.com", "/\t/evil.com", "/\n/evil.com", "/\r/evil.com",
    "/ /evil.com", "https://evil.com", "http:evil.com", "javascript:alert(1)", `/${String.fromCharCode(0xa0)}/evil.com`, `/${String.fromCharCode(0x2028)}/evil.com`, `/${String.fromCharCode(0x200b)}/evil.com`,
    "%2F%2Fevil.com", "evil.com", "", "/api/auth/logout", "/API/auth/logout", "/portal/../api/x", "/api",
  ];
  for (const a of angriffe) {
    const z = sicheresZiel(a, "/portal");
    assert.equal(herkunft(z), new URL(BASIS).origin, `Angriff ${JSON.stringify(a)} → ${z}`);
    assert.ok(!/^\/api(\/|$)/i.test(z), `API-Ziel ${JSON.stringify(a)} → ${z}`);
  }
});

test("Steuerzeichen, Backslash und API führen zum Standard", () => {
  for (const a of ["/\t/evil.com", "/\\evil.com", "/api/auth/logout", "/portal/../api/x", "//evil.com"]) {
    assert.equal(sicheresZiel(a, "/std"), "/std", JSON.stringify(a));
  }
});

test("interne Pfade bleiben erhalten (normalisiert)", () => {
  assert.equal(sicheresZiel("/portal"), "/portal");
  assert.equal(sicheresZiel("/portal/anfragen/A-123?tab=dok#x"), "/portal/anfragen/A-123?tab=dok#x");
  assert.equal(sicheresZiel("/portal/boerse/%2F%2Fevil.com"), "/portal/boerse/%2F%2Fevil.com");
  assert.equal(sicheresZiel("/portal/./profil"), "/portal/profil");
  test("Klick-IDs nur im Arbeitsspeicher, mit der Anfrage nur der Typ", () => {
    herkunftErfassen({ href: "https://www.oekoinvest.com/agri-pv?gclid=ABC-geheim-123&utm_source=google&utm_medium=cpc", referrer: "https://www.google.com/" });
    const h = herkunft({ href: "https://www.oekoinvest.com/kontakt" });
    assert.equal(h.klick_id_typ, "gclid");
    assert.ok(!JSON.stringify(h).includes("ABC-geheim-123"));
    assert.equal(h.kanal, "Anzeige");
    assert.deepEqual(klickIds(), { gclid: "ABC-geheim-123" });
  });
  test("Einstieg über Angebots-Code: nur Hash", () => {
    herkunftErfassen({ href: "https://www.oekoinvest.com/angebot/PERS0NLICH", referrer: "" });
    const h = herkunft({ href: "https://www.oekoinvest.com/einladung/tok123" });
    assert.equal(h.einstieg, `/angebot/h-${codeHash("PERS0NLICH")}`);
    assert.equal(h.seite, "/einladung");
    assert.ok(!JSON.stringify(h).includes("PERS0NLICH") && !JSON.stringify(h).includes("tok123"));
  });
  test("KI-Herkunft vor Suchmaschine und Kampagne", () => {
    assert.equal(kanal({ referrer: "gemini.google.com" }), "KI-Assistent");
    assert.equal(kanal({ referrer: "copilot.microsoft.com" }), "KI-Assistent");
    assert.equal(kanal({ referrer: "chatgpt.com" }), "KI-Assistent");
    assert.equal(kanal({ utm_source: "chatgpt.com" }), "KI-Assistent");
    assert.equal(kanal({ referrer: "perplexity.ai" }), "KI-Assistent");
    assert.equal(kanal({ referrer: "google.de" }), "Suchmaschine");
    assert.equal(kanal({ referrer: "bing.com" }), "Suchmaschine");
    assert.equal(kanal({ utm_source: "newsletter", utm_medium: "email" }), "E-Mail");
    assert.equal(kanal({}), "Direkt");
  });
});

