// src/lib/plattform/server/rechte.js
//
// Durchsetzung der Backoffice-Unterrollen (src/lib/plattform/rechte.js):
//  - APIs: route() ruft adminRechtPruefen() für jede Anfrage auf /api/admin/** (nach dem Lesen des Bodys,
//    damit z. B. /api/admin/status die Objektart kennt). Option `recht` im route()-Aufruf überschreibt die
//    Ableitung aus dem Pfad.
//  - Seiten: server/seite.js prüft /portal/admin/** über seitenRechtOk().
// Nicht-Admins werden hier nicht geprüft (dafür sorgt `admin: true` in route() bzw. portalNutzer).

import { PlattformFehler } from "../fehler";
import { BEREICHE, STUFE_LABEL, apiAnforderungen, fehlendeRechte, darfLesen, seitenBereich } from "../rechte";

export function adminRechtPruefen(nutzer, { request, body, params, recht } = {}) {
  const pfad = request?.nextUrl?.pathname || "";
  if (!pfad.startsWith("/api/admin/") && !recht) return;
  if (!nutzer?.rollen?.includes("admin")) return;
  const fehlt = fehlendeRechte(nutzer, apiAnforderungen({ pfad, methode: request.method, body, params, recht }));
  if (fehlt.length) {
    const f = fehlt[0];
    throw new PlattformFehler(403, `Ihre Backoffice-Rolle erlaubt im Bereich „${BEREICHE[f.bereich] || f.bereich}“ kein ${STUFE_LABEL[f.stufe]}.`, "recht");
  }
}

/** Darf der Nutzer die Admin-Seite (Pfad) sehen? */
export function seitenRechtOk(nutzer, pfad) {
  const bereich = seitenBereich(pfad);
  return !bereich || darfLesen(nutzer, bereich);
}

// ================================================================ Vorgänge

function vorgangListenEintrag(db, vg, admin) {
  const z = nutzerById(db, vg.zustaendigId);
  const letzte = vg.statusVerlauf[vg.statusVerlauf.length - 1];
  return {
    id: vg.id,
    typ: vg.typ,
    status: vg.status,
    erstelltAm: vg.erstelltAm,
    geaendertAm: vg.geaendertAm,
    kontakt: { vorname: vg.kontakt.vorname, nachname: vg.kontakt.nachname, firma: vg.kontakt.firma, email: vg.email },
    nutzerId: admin ? vg.nutzerId : undefined,
    zustaendig: z ? kurz(z) : null,
    flaecheId: vg.flaecheId,
    letzterKommentar: letzte?.kommentar || "",
  };
}

export async function vorgaenge(n, { alle = false, status, typ, q } = {}) {
  if (!n) throw new PlattformFehler(401, "Bitte melden Sie sich an.");
  if (alle) adminNoetig(n);
  const db = await lesen();
  let liste = alle ? db.vorgaenge : db.vorgaenge.filter((x) => x.nutzerId === n.id);
  if (status) liste = liste.filter((x) => x.status === status);
  if (typ) liste = liste.filter((x) => x.typ === typ);
  if (q) {
    const s = String(q).toLowerCase();
    liste = liste.filter((x) => [x.id, x.email, x.kontakt.vorname, x.kontakt.nachname, x.kontakt.firma].join(" ").toLowerCase().includes(s));
  }
  return liste.sort(nachDatum()).map((x) => vorgangListenEintrag(db, x, alle));
}

export async function vorgang(n, id) {
  if (!n) throw new PlattformFehler(401, "Bitte melden Sie sich an.");
  const db = await lesen();
  const vg = objekt(db, "vorgang", id);
  if (!vg) throw nichtGefunden("Anfrage nicht gefunden.");
  if (!istAdmin(n) && vg.nutzerId !== n.id) throw verboten();
  const out = { ...vg, zustaendig: kurz(nutzerById(db, vg.zustaendigId)) };
  if (istAdmin(n)) out.nutzer = kurz(nutzerById(db, vg.nutzerId));
  else {
    delete out.ip;
    delete out.herkunft;
  }
  return out;
}

