        {a && summe === 0 ? (
          <Leer icon={Handshake} titel="Noch keine Anfragen über Gruppe oder Partner" text="Sobald Verweise mit Kennung eingebaut sind, erscheinen die Anfragen hier – je Kanal, Kennung und Land." />
