            {daten.register.map((e) => (
              <tr key={e.kennung}>
                <th scope="row" className={cn(zelle, "font-mono text-[13px] font-medium text-ink-900")}>{e.kennung}</th>
                <td className={zelle}>{e.artLabel}</td>
                <td className={zelle}>{e.land}</td>
