      assert.equal(res.headers.get("location"), "/", k);
    }
  });
  test("HEAD verhält sich wie GET", async () => {
    const { HEAD } = await import("../../app/p/[kennung]/route.js");
    const res = await HEAD(new Request(`${BASIS}/p/x`), { params: Promise.resolve({ kennung: "beispiel-gruppe-de" }) });
    pruefeSicher(res, "HEAD");
  });
});

